const payload = $json.body || $json || {};
const extractedText = String(payload.extracted_text || '').trim().slice(0, 16000);
const fileName = String(payload.file_name || 'Candidate_CV.pdf').trim();
const countryCode = String(payload.country_code || 'AE').toUpperCase();
const countryNameAr = String(payload.country_name_ar || 'الإمارات العربية المتحدة');
const countryNameEn = String(payload.country_name_en || 'United Arab Emirates');
const manualIndustryId = String(payload.manual_industry_id || '').trim();
const hasTextLayer = payload.has_text_layer !== false && extractedText.replace(/\s+/g, '').length >= 40;
const industries = Array.isArray(payload.industries) && payload.industries.length
  ? payload.industries
  : [
      { id: 'engineering', name_en: 'Engineering & Construction', name_ar: 'الهندسة والإنشاءات' },
      { id: 'it-software', name_en: 'IT, Software & AI', name_ar: 'تكنولوجيا المعلومات والبرمجيات' },
      { id: 'finance-accounting', name_en: 'Finance & Accounting', name_ar: 'المالية والمحاسبة' },
      { id: 'sales-marketing', name_en: 'Sales & Marketing', name_ar: 'المبيعات والتسويق' },
      { id: 'healthcare', name_en: 'Healthcare & Medical', name_ar: 'الرعاية الصحية والطب' },
      { id: 'hr-admin', name_en: 'HR & Administration', name_ar: 'الموارد البشرية والإدارة' },
      { id: 'logistics-supply', name_en: 'Logistics & Supply Chain', name_ar: 'اللوجستيات وسلاسل الإمداد' },
      { id: 'hospitality-retail', name_en: 'Hospitality & Retail', name_ar: 'الضيافة والتجزئة' },
      { id: 'real-estate', name_en: 'Real Estate & Property', name_ar: 'العقارات وإدارة الأملاك' },
      { id: 'legal', name_en: 'Legal & Compliance', name_ar: 'الشؤون القانونية والامتثال' },
      { id: 'education', name_en: 'Education & Training', name_ar: 'التعليم والتدريب' },
      { id: 'design-media', name_en: 'Design, Media & Creative', name_ar: 'التصميم والإعلام' }
    ];
const fallback = (payload.fallback && typeof payload.fallback === 'object') ? payload.fallback : {};

const allowedIndustryIds = industries.map((i) => i.id);
const industriesListText = industries
  .map((i) => `- "${i.id}": ${i.name_en || i.id} (${i.name_ar || ''})`)
  .join('\n');

const userPrompt = [
  `FILE NAME: ${fileName}`,
  `TARGET GCC COUNTRY: ${countryCode} (${countryNameEn} / ${countryNameAr})`,
  manualIndustryId ? `USER SELECTED INDUSTRY HINT: ${manualIndustryId}` : `USER SELECTED INDUSTRY HINT: none (detect automatically)`,
  `HAS READABLE TEXT LAYER: ${hasTextLayer ? 'yes' : 'no (scanned image / minimal text)'}`,
  ``,
  `ALLOWED INDUSTRY IDs (MUST PICK EXACTLY ONE OF THESE IDs):`,
  industriesListText,
  ``,
  `RAW EXTRACTED CV TEXT:`,
  extractedText || '(No selectable text extracted — likely a scanned image PDF. Infer conservatively from file name only and note low ATS readability.)',
].join('\n');

return [{
  json: {
    userPrompt,
    allowedIndustryIds,
    manualIndustryId,
    hasTextLayer,
    fileName,
    countryCode,
    countryNameAr,
    countryNameEn,
    fallback,
  },
}];

const rawOutput = String($json.output || $json.text || '').trim();
const prep = $('prepareCvPrompt').first().json || {};
const allowed = new Set(Array.isArray(prep.allowedIndustryIds) ? prep.allowedIndustryIds : []);
const fb = prep.fallback || {};

const cleaned = rawOutput
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed = null;
try {
  parsed = JSON.parse(cleaned);
} catch {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch {
      parsed = null;
    }
  }
}

if (!parsed || typeof parsed !== 'object') {
  return [{
    json: {
      ok: false,
      ai_parsed: false,
      error: 'Unparseable AI output',
    },
  }];
}

const cleanStr = (v, max = 160) => (typeof v === 'string' ? v.replace(/\s+/g, ' ').trim().slice(0, max) : '');

const rawEmail = cleanStr(parsed.candidate_email, 120).toLowerCase();
const candidate_email = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(rawEmail)
  ? rawEmail
  : (fb.candidate_email || '');

const rawPhone = cleanStr(parsed.candidate_phone, 40);
const candidate_phone = rawPhone.replace(/[^\d]/g, '').length >= 8
  ? rawPhone
  : (fb.candidate_phone || '');

const candidate_name = cleanStr(parsed.candidate_name, 90) || fb.candidate_name || '';
const job_title = cleanStr(parsed.job_title, 110) || fb.job_title || '';

const rawIndustry = cleanStr(parsed.detected_industry_id, 50);
const detected_industry_id = (prep.manualIndustryId && allowed.has(prep.manualIndustryId))
  ? prep.manualIndustryId
  : (allowed.has(rawIndustry) ? rawIndustry : (fb.detected_industry_id || 'it-software'));

const rawYears = Number(parsed.years_experience);
const years_experience = Number.isFinite(rawYears)
  ? Math.max(0, Math.min(40, Math.round(rawYears)))
  : (Number.isFinite(Number(fb.years_experience)) ? Number(fb.years_experience) : 3);

const rawScore = Number(parsed.ats_score);
const ats_score = Number.isFinite(rawScore)
  ? Math.max(35, Math.min(98, Math.round(rawScore)))
  : (Number.isFinite(Number(fb.ats_score)) ? Number(fb.ats_score) : 74);

const detected_skills = Array.isArray(parsed.detected_skills)
  ? Array.from(new Set(
      parsed.detected_skills
        .map((s) => cleanStr(s, 48))
        .filter((s) => s.length >= 2)
    )).slice(0, 10)
  : (Array.isArray(fb.detected_skills) ? fb.detected_skills : []);

const summary_ar = cleanStr(parsed.summary_ar, 450);
const summary_en = cleanStr(parsed.summary_en, 450);

return [{
  json: {
    ok: true,
    ai_parsed: true,
    candidate_name,
    candidate_email,
    candidate_phone,
    detected_industry_id,
    job_title,
    years_experience,
    detected_skills,
    ats_score,
    summary_ar,
    summary_en,
  },
}];
